function calculateTotal(items: {price:number, qty:number}[]) {
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    total += item.price * item.qty;
  }
  // TODO remove console debug
  console.log("total", total);
  return total;
}

